// Target distribution across 200 test cases:
//   accepted: 90 (45%)
//   rejected: 90 (45%)
//   ignored:  20 (10%)
// Random weighted choice — statistical variance over 200 trials is small.
const r = Math.random();
let decision, approved, ignored;
if (r < 0.10) {
  decision = 'ignore';
  approved = false;
  ignored = true;
} else if (r < 0.55) {
  decision = 'accept';
  approved = true;
  ignored = false;
} else {
  decision = 'reject';
  approved = false;
  ignored = false;
}
return [{
  json: {
    decision,
    approved,
    ignored,
    // Match the shape that Telegram sendAndWait emits so downstream IF works unchanged
    data: { approved }
  }
}];
